var EXTRA=[{dot:"gray",j:"EFORT Open Reviews",h:"Fratture periprotesiche del ginocchio: stabilità dell'impianto e osso decidono la scelta",v:"Revisione narrativa: stabilità del componente e qualità ossea pesano più della morfologia della frattura; fissazione con placca bloccata o chiodo retrogrado se l'impianto è stabile, revisione con steli, coni o manicotti se è mobilizzato.",pmid:"42825413",doi:"10.1530/EOR-2026-0075",temi:["frattura periprotesica", "protesi totale", "revisione"]},{dot:"gray",j:"Journal of Sports Sciences",h:"Carichi femororotulei in corsa: forza al suolo e flessione ne sono i predittori",v:"Studio di laboratorio su corridori con modello muscoloscheletrico: picco di forza verticale, flessione massima del ginocchio e angolo di appoggio del piede predicono i carichi; stima da laboratorio, nessun esito clinico.",pmid:"42829958",doi:"10.1080/02640414.2026.2741753",temi:["femororotulea", "corsa", "carico articolare"]},{dot:"gray",j:"Journal of Sports Sciences",h:"Calcio: nel cambio di direzione le donne assorbono più energia al ginocchio",v:"Venti atleti di calcio in laboratorio, prima e dopo fatica: le donne mostrano maggiore assorbimento di energia al ginocchio e angolo di appoggio del piede maggiore; campione piccolo, nessuna lesione osservata.",pmid:"42829962",doi:"10.1080/02640414.2026.2741752",temi:["prevenzione LCA", "calcio", "biomeccanica"]},{dot:"gray",j:"BMC Surgery",h:"Acido tranexamico nella TKA primaria: meno perdita di sangue e trasfusioni nei trial",v:"Meta-analisi di RCT: riduce perdita ematica e trasfusioni senza aumento rilevato di trombosi venosa profonda; eterogeneità molto alta sulla perdita di sangue e segni di effetti dei piccoli studi sulle trasfusioni.",pmid:"42823775",doi:"10.1186/s12893-026-04060-2",temi:["protesi totale", "acido tranexamico", "emorragia"]},{dot:"gray",j:"Indian Journal of Orthopaedics",h:"TKA nell'artrite reumatoide e nell'artrosi: esiti funzionali simili, complicanze diverse",v:"Meta-analisi di studi osservazionali e registri: funzione e sopravvivenza dell'impianto comparabili; profili di complicanze diversi per malattia, in parte attenuati nell'analisi appaiata per sesso.",pmid:"42824590",doi:"10.1007/s43465-026-01803-4",temi:["protesi totale", "artrite reumatoide", "complicanze"]},{dot:"gray",j:"Frontiers in Surgery",h:"Cellulosa rigenerata ossidata nelle protesi: effetto modesto su indicatori surrogati",v:"Revisione sistematica di anca e ginocchio: meno perdita ematica rispetto a nessun trattamento, nessun vantaggio chiaro sugli altri emostatici topici né sulle trasfusioni; gli autori non sostengono l'uso di routine.",pmid:"42827511",doi:"10.3389/fsurg.2026.1900156",temi:["protesi totale", "emostasi", "revisione sistematica"]},{dot:"gray",j:"Indian Journal of Orthopaedics",h:"Dopo TKA, FJS-12 e KOOS misurano cose diverse: il FJS-12 discrimina meglio più tardi",v:"Studio prospettico in pazienti indiani, versione in kannada: entrambi i questionari migliorano e sono affidabili; il KOOS raggiunge prima l'effetto soffitto, il FJS-12 continua a discriminare nel recupero tardivo.",pmid:"42824222",doi:"10.1007/s43465-026-01712-6",temi:["protesi totale", "PROM", "FJS-12"]},{dot:"gray",j:"Indian Journal of Orthopaedics",h:"Rapporto neutrofili/linfociti preoperatorio e dolore dopo TKA: associazione retrospettiva",v:"Studio retrospettivo monocentrico: un rapporto più alto si associa a dolore postoperatorio e consumo di oppioidi maggiori nei primi tre giorni; associazione, non causalità, e nessuna soglia validata.",pmid:"42824528",doi:"10.1007/s43465-026-01792-4",temi:["protesi totale", "dolore postoperatorio", "biomarcatore"]},{dot:"gray",j:"Clinical Anatomy",h:"Il muscolo articolare del ginocchio è davvero indipendente? Revisione anatomica",v:"Revisione narrativa di otto studi anatomici: origine e inserzione concordano, ma numero di fasci, lunghezza e continuità con il vasto intermedio no; la definizione resta controversa, con ricadute sull'interpretazione delle immagini e sul dolore anteriore.",pmid:"42817925",doi:"10.1002/ca.70236",temi:["anatomia", "apparato estensore", "dolore anteriore"]}];

var SCOPERTE=[{t:"Risonanza con diffusione: la cartilagine «si vede» prima che la radiografia cambi",v:"Uno studio prospettico di imaging (71 partecipanti, 40 con radiografie a 3 anni; JMRI) mostra che la diffusività media del condilo femorale mediale distingue il ginocchio sano dalle prime fasi di artrosi (AUC 0,90) molto meglio della mappa T2 (AUC 0,55), e migliora la previsione della progressione radiografica (AUC 0,80 sul restringimento articolare); intervalli di confidenza non riportati nell'abstract. Vale la deviazione perché sposta la cartilagine dall'immagine alla microstruttura, il terreno su cui lavorano AMIC e minced cartilage; è un lavoro di imaging su casistica piccola, non un esito di trattamento.",pmid:"42817870",doi:"10.1002/jmri.70562",temi:["cartilagine", "risonanza magnetica", "artrosi precoce"]},{t:"Nove chatbot rispondono alle domande dei pazienti sulla protesi totale: sette ortopedici li valutano alla cieca",v:"Uno studio trasversale turco (The Knee) ha chiesto a nove chatbot cinque domande frequenti sulla TKA e le ha fatte valutare a sette specialisti ciechi rispetto al modello: tutte le scale differiscono per modello (p ≤ 0,001); DeepSeek ha la media DISCERN più alta (70,57 ± 2,64), ChatGPT-4o la migliore comprensibilità (PEMAT-U 86,62 ± 4,45). Vale la deviazione perché è l'intelligenza artificiale che i pazienti già usano prima di arrivare da te; sono cinque domande e un solo giorno di interrogazione, e la qualità non dice se la risposta sia clinicamente giusta.",pmid:"42828836",doi:"10.1016/j.knee.2026.104648",temi:["intelligenza artificiale", "protesi totale", "informazione al paziente"]},{t:"Prevedere chi non risponde alla riabilitazione dopo TKA: un modello austriaco su oltre 5.000 pazienti",v:"Dati di registro di quattro centri di riabilitazione austriaci (5.463 pazienti, 2018-2024) addestrano modelli di apprendimento automatico per prevedere il mancato raggiungimento della differenza minima rilevante: AUC 0,771 per il Timed Up and Go, 0,704 per il WOMAC, 0,770 per l'EQ-5D, con calibrazione variabile; intervalli non riportati nell'abstract. Vale la deviazione perché mostra come un valore di partenza elevato domini la previsione (effetto soffitto), un limite metodologico che riguarda anche le tue misure di esito; è solo validazione su dati retrospettivi, senza prova prospettica.",pmid:"42827926",doi:"10.3389/fresc.2026.1930836",temi:["intelligenza artificiale", "riabilitazione", "protesi totale"]}];

var SOC={"1": {"video": "Dopo l'operazione al crociato con i tendini della coscia, la forza dei muscoli flessori dipende da come si misura. Uno studio svedese ha usato quattro test su 68 pazienti, circa un anno dopo l'intervento.\n\nDa seduti, il lato operato arriva al 98% di quello sano. Con un esercizio in cui si frena il corpo in avanti, all'85%. In due prove da sdraiati a pancia in giù, a circa il 64% e il 55%. La differenza fra la prima e l'ultima prova è di 43,9 punti, con un intervallo da 39,9 a 47,8.\n\nNei pazienti operati con tendine rotuleo o quadricipitale le differenze fra prove sono molto minori. Non sappiamo se i deficit delle prove da sdraiati contino per il rientro allo sport: le prove sono state fatte nella stessa seduta e il gruppo di confronto è piccolo.\nFonte: PubMed, PMID 42829679.", "linkedin": "Simmetria di forza dei flessori dopo LCA con hamstring (Journal of Experimental Orthopaedics, ottobre 2026): studio prospettico di livello II del registro Project ACL, Göteborg; 68 pazienti con innesto hamstring a una mediana di 12 mesi, 33 controlli con innesto rotuleo (32) o quadricipitale (1).\n\nLSI: 98,4% ± 10,5% Biodex seduto; 85,3% ± 14,4% Nordic hamstring; 64,1% ± 13,6% ISO90 con dorsiflessione; 54,5% ± 16,0% ISO90 con flessione plantare. Differenza Biodex-ISO90 PF 43,9% (IC 95% 39,9-47,8). Quota con LSI ≥90%: 80% contro 3%. Nei controlli la differenza Biodex-ISO90 PF è 6,1% (IC 95% 1,7-10,6).\n\nLimite: test nella stessa seduta e non randomizzati, controllo piccolo (NordBord in 18), nessun esito duro; la rilevanza clinica delle prove prone è incerta. Il controllo è quasi tutto rotuleo: non è il retto femorale.\nFonte: PubMed, PMID 42829679.", "instagram": "Forza dei flessori dopo il crociato: dipende dal test.\nIn 68 pazienti, un anno dopo, la forza del lato operato è il 98% di quello sano da seduti e circa il 55% in una prova da sdraiati a pancia in giù.\n\nNei 33 pazienti con tendine rotuleo o quadricipitale le differenze fra prove sono molto minori.\n\nLimite: prove nella stessa seduta, nessun esito sul rientro allo sport.\nFonte: PubMed, PMID 42829679.", "pazienti": "Dopo l'intervento al legamento crociato con tendini della parte posteriore della coscia, la forza di quei muscoli può sembrare quasi normale in un test e molto ridotta in un altro.\n\nIn uno studio svedese su 68 persone, circa un anno dopo l'operazione, il test da seduti mostrava una forza quasi uguale a quella dell'altra gamba; due test da sdraiati mostravano valori molto più bassi.\n\nLo studio non dice se questo conti per il ritorno allo sport. Un solo test può non mostrare tutto: se ne parla con lo specialista e con il fisioterapista.\nFonte: PubMed, PMID 42829679."}};

var SOCV={"1": {"video": {"chir": ["Simmetria di forza dei flessori dopo LCA con hamstring: dipende dal test. Uno studio prospettico del registro Project ACL di Göteborg, nel Journal of Experimental Orthopaedics, ha misurato 68 pazienti a una mediana di dodici mesi con quattro prove diverse.", "Biodex da seduti: simmetria 98,4%. Nordic hamstring: 85,3%. Le due prove isometriche prone a novanta gradi: 64,1% e 54,5%. Fra Biodex e prova prona con flessione plantare la differenza è di 43,9 punti, intervallo di confidenza da 39,9 a 47,8. Sopra la soglia del 90% sta l'80% dei pazienti al Biodex e il 3% alla prova prona.", "Nei 33 controlli con innesto rotuleo o quadricipitale le differenze fra test sono di circa sei punti. Il limite: prove nella stessa seduta, controllo piccolo, nessun esito duro; non sappiamo se i deficit delle prove prone contino per il rientro.\nFonte: PubMed, PMID 42829679."], "misto": ["Dopo l'operazione al crociato con i tendini della coscia, la forza dei muscoli flessori dipende da come si misura. Uno studio svedese ha usato quattro test su 68 pazienti, circa un anno dopo l'intervento.", "Da seduti, il lato operato arriva al 98% di quello sano. Con un esercizio in cui si frena il corpo in avanti, all'85%. In due prove da sdraiati a pancia in giù, a circa il 64% e il 55%. La differenza fra la prima e l'ultima prova è di 43,9 punti, con un intervallo da 39,9 a 47,8.", "Nei pazienti operati con tendine rotuleo o quadricipitale le differenze fra prove sono molto minori. Non sappiamo se i deficit delle prove da sdraiati contino per il rientro allo sport: le prove sono state fatte nella stessa seduta e il gruppo di confronto è piccolo.\nFonte: PubMed, PMID 42829679."], "pazienti": ["Dopo l'operazione al legamento crociato con tendini presi dalla parte posteriore della coscia, la forza di quei muscoli dipende da come viene misurata. Uno studio svedese ha usato quattro test su 68 persone, circa un anno dopo l'intervento.", "In un test eseguito da seduti la gamba operata arriva quasi al livello dell'altra. In altri test, eseguiti in posizioni diverse, resta molto più indietro: in uno dei due test da sdraiati, poco più della metà.", "Lo studio non dice se questa differenza conti per tornare allo sport, e il gruppo di confronto è piccolo. Un solo test può non mostrare tutto: se ne parla con lo specialista e con il fisioterapista.\nFonte: PubMed, PMID 42829679."]}, "linkedin": {"chir": ["Simmetria di forza dei flessori dopo LCA con hamstring (Journal of Experimental Orthopaedics, ottobre 2026): studio prospettico di livello II del registro Project ACL, Göteborg; 68 pazienti con innesto hamstring a una mediana di 12 mesi, 33 controlli con innesto rotuleo (32) o quadricipitale (1).", "LSI: 98,4% ± 10,5% Biodex seduto; 85,3% ± 14,4% Nordic hamstring; 64,1% ± 13,6% ISO90 con dorsiflessione; 54,5% ± 16,0% ISO90 con flessione plantare. Differenza Biodex-ISO90 PF 43,9% (IC 95% 39,9-47,8). Quota con LSI ≥90%: 80% contro 3%. Nei controlli la differenza Biodex-ISO90 PF è 6,1% (IC 95% 1,7-10,6).", "Limite: test nella stessa seduta e non randomizzati, controllo piccolo (NordBord in 18), nessun esito duro; la rilevanza clinica delle prove prone è incerta. Il controllo è quasi tutto rotuleo: non è il retto femorale.\nFonte: PubMed, PMID 42829679."], "misto": ["Forza dei muscoli flessori dopo il crociato con i tendini della coscia: dipende da come si misura. Studio svedese su 68 pazienti, circa un anno dopo l'operazione, con quattro test diversi.", "Da seduti: 98,4% della forza del lato sano. Con il Nordic hamstring: 85,3%. In due prove da sdraiati: 64,1% e 54,5%. Nei 33 pazienti con tendine rotuleo o quadricipitale le differenze fra test sono di circa sei punti.", "Limite: prove nella stessa seduta e gruppo di confronto piccolo; non è noto se i deficit delle prove da sdraiati contino per il rientro allo sport.\nFonte: PubMed, PMID 42829679."], "pazienti": ["Dopo l'intervento al legamento crociato con tendini della parte posteriore della coscia, la forza di quei muscoli può sembrare quasi normale in un test e molto ridotta in un altro.", "In uno studio svedese su 68 persone, circa un anno dopo l'operazione, il test da seduti mostrava una forza quasi uguale a quella dell'altra gamba; due test da sdraiati mostravano valori molto più bassi.", "Lo studio non dice se questo conti per il ritorno allo sport. Un solo test può non mostrare tutto: se ne parla con lo specialista e con il fisioterapista.\nFonte: PubMed, PMID 42829679."]}, "instagram": {"chir": ["LCA con hamstring: la simmetria dei flessori dipende dal test.", "68 pazienti, 12 mesi: LSI 98,4% (Biodex) contro 54,5% (ISO90 PF); differenza 43,9% (IC 95% 39,9-47,8).", "Prospettico, controllo quasi tutto rotuleo, nessun esito duro.\nFonte: PubMed, PMID 42829679."], "misto": ["Crociato con tendini della coscia: la forza dei flessori dipende dal test.", "68 pazienti, un anno dopo: 98% da seduti, circa 55% in una prova da sdraiati a pancia in giù.", "Non sappiamo se la differenza conti per il rientro allo sport.\nFonte: PubMed, PMID 42829679."], "pazienti": ["Dopo l'operazione al crociato, un solo test della forza può non dire tutto.", "In uno studio su 68 persone il risultato cambiava molto da un test all'altro.", "Non è noto se questo influisca sul ritorno allo sport: se ne parla con lo specialista.\nFonte: PubMed, PMID 42829679."]}, "reel": {"chir": ["Forza dei flessori dopo LCA hamstring: 98% o 55%?", "Dipende dal test: Biodex 98,4%, ISO90 PF 54,5%; differenza 43,9% (IC 95% 39,9-47,8).", "Controllo rotuleo: differenza circa 6%. Livello II, nessun esito duro."], "misto": ["Forza dopo il crociato: 98% o 55%?", "Dipende dal test: da seduti 98%, da sdraiati a pancia in giù circa 55%.", "Non è noto se conti per il rientro allo sport."], "pazienti": ["Dopo il crociato la forza si misura in più modi.", "In uno studio su 68 persone il risultato cambiava molto da un test all'altro.", "Un solo test può non dire tutto: se ne parla con lo specialista."]}}};

var TAGS={"1": {"linkedin": "#Ortopedia #LCA #RitornoAlloSport", "instagram": "#ortopedia #ginocchio #legamentocrociato #lca #ritornoallosport #forzamuscolare #medicinadellosport #ortopediaticino #medicinabasatasulleprove #traumatologiadellosport", "kw": "legamento crociato anteriore, forza muscolare dopo operazione, test di forza ginocchio"}};

var NLB={"1": {"prof": ["Dopo LCA con hamstring la simmetria dei flessori dipende dal test: dal 98% al 55%", "Uno studio prospettico del registro Project ACL (Journal of Experimental Orthopaedics, ottobre 2026; Göteborg) su 68 pazienti operati con hamstring, a una mediana di 12 mesi, misura la simmetria di forza dei flessori con quattro test: 98,4% con il Biodex seduto, 85,3% con il Nordic hamstring, 64,1% e 54,5% con le due prove isometriche prone a 90° (differenza Biodex-ISO90 PF 43,9%; IC 95% 39,9-47,8). Supera la soglia del 90% l'80% dei pazienti al Biodex e il 3% alla prova prona con flessione plantare; nei 33 controlli con innesto rotuleo (32) o quadricipitale (1) la differenza fra gli stessi test è di circa 6 punti.", "Nota critica: test eseguiti nella stessa seduta e non randomizzati, controllo piccolo (NordBord in 18) e quasi tutto rotuleo, nessun esito duro; la rilevanza clinica dei deficit nelle prove prone resta incerta."], "mix": ["Dopo il crociato con i tendini della coscia, la forza dei flessori dipende da come la si misura", "Uno studio svedese ha misurato la forza dei muscoli che piegano il ginocchio in 68 pazienti operati al legamento crociato con tendini presi dalla parte posteriore della coscia, circa un anno dopo l'intervento, con quattro prove diverse. Da seduti il lato operato arriva al 98% di quello sano; con un esercizio in cui si frena il corpo in avanti (Nordic) all'85%; con due prove da sdraiati a pancia in giù a circa il 64% e il 55%. Nei 33 pazienti operati con tendine rotuleo o quadricipitale le differenze fra le prove sono molto minori.", "Nota sul limite: le prove sono state fatte nella stessa seduta, il gruppo di confronto è piccolo e non si sa se i deficit rilevati nelle prove da sdraiati contino per il rientro allo sport."], "paz": ["Dopo l'operazione al crociato, la forza dei muscoli dietro la coscia dipende dal tipo di test", "In uno studio svedese su 68 persone operate al legamento crociato con tendini presi dalla parte posteriore della coscia, circa un anno dopo la forza di quei muscoli risultava quasi uguale a quella dell'altra gamba in un test eseguito da seduti, ma molto più bassa in altri test eseguiti in posizioni diverse. Questo indica che un solo test può non mostrare tutto.", "Lo studio non dice se queste differenze abbiano conseguenze sulla ripresa dello sport: se ne parla con lo specialista e con il fisioterapista."], "kw": "legamento crociato anteriore, forza muscolare dopo operazione, test di forza ginocchio"}, "2": {"prof": ["UKA laterale fixed-bearing in pazienti ≤55 anni: nessuna revisione del componente laterale", "Una serie retrospettiva da database prospettico (Journal of Experimental Orthopaedics, ottobre 2026; Stoccarda) su 84 UKA laterali fixed-bearing in 80 pazienti di 55 anni o meno, follow-up medio 5,3 ± 1,9 anni, non registra revisioni del componente laterale; la sopravvivenza libera da reintervento a 5 anni è 92,5% (IC 95% 86,8-98,2). Sette reinterventi: quattro UKA mediali aggiuntive, due artroscopie, un DAIR. HKA da 4,8° ± 4,7° a 2,0° ± 2,8° di valgo; OKS 43,8 ± 5,7.", "Nota critica: nessun gruppo di confronto; con zero eventi su 84 il limite superiore indicativo del tasso di revisione è circa 3,6% (regola del tre); follow-up medio di cinque anni; l'associazione fra varismo e progressione mediale poggia su quattro ginocchia."], "mix": ["Protesi parziale esterna del ginocchio sotto i 55 anni: nessuna revisione a cinque anni", "Un centro tedesco ha seguito per circa cinque anni 80 pazienti di 55 anni o meno, operati con una protesi che sostituisce solo la parte esterna del ginocchio (84 ginocchia). Nella parte esterna nessuna protesi ha dovuto essere sostituita o rimossa; in sette ginocchia è stato necessario un altro intervento, in quattro dei quali una protesi anche nella parte interna. I punteggi funzionali erano alti (Oxford Knee Score medio 43,8).", "Nota sul limite: non c'è un gruppo di confronto, il periodo è di circa cinque anni e con zero eventi su 84 non si può escludere che il rischio reale sia di qualche punto percentuale."], "paz": ["Protesi parziale esterna del ginocchio in persone giovani: buoni risultati a cinque anni in uno studio", "Un ospedale tedesco ha seguito 80 persone di 55 anni o meno con una protesi che sostituisce solo la parte esterna del ginocchio. Dopo circa cinque anni nessuna protesi aveva dovuto essere cambiata nella parte esterna e i punteggi erano alti; in sette ginocchia c'è stato un altro intervento, in quattro casi per la parte interna.", "Lo studio non ha un gruppo di confronto e dura circa cinque anni: non permette di dire come andranno le cose più avanti."], "kw": "protesi parziale esterna ginocchio, protesi monocompartimentale giovani, artrosi lato esterno ginocchio"}, "3": {"prof": ["TKA robotica: la variazione dell'obliquità della rima articolare non peggiora l'equilibrio in flessione", "Una serie retrospettiva di un chirurgo (Journal of Experimental Orthopaedics, ottobre 2026; Hospital for Special Surgery) su 402 TKA primarie robot-assistite rileva un cambio di tipo CPAK in 300 ginocchia (74,6%) e di zona di obliquità della rima (JLO) in 221 (55,0%). Una variazione maggiore di JLO si associa a minore squilibrio in flessione (β -0,060; p<0,001) e a una lassità in estensione più stretta (β -0,055; p=0,002); nessuna associazione con il miglioramento del KOOS JR. Intervalli di confidenza non riportati nell'abstract.", "Nota critica: coorte di un solo chirurgo, senza confronto; l'equilibrio è misurato con l'impianto di prova e non è un esito clinico; la piattaforma robotica non è indicata."], "mix": ["Protesi totale con robot: cambiare l'inclinazione della linea articolare non peggiora l'equilibrio", "Un centro americano ha analizzato 402 protesi totali di ginocchio impiantate da un chirurgo con assistenza robotica. In oltre la metà dei casi la linea di appoggio fra femore e tibia è stata inclinata in modo diverso da quella di partenza, e più cambiava, meglio risultava l'equilibrio dei tessuti molli in flessione (p<0,001). Il cambiamento non era legato a un miglioramento del punteggio riferito dal paziente.", "Nota sul limite: un solo chirurgo, nessun gruppo di confronto, e l'equilibrio è misurato in sala operatoria, non è il risultato per il paziente."], "paz": ["Protesi totale del ginocchio con robot: uno studio su 402 interventi", "Un ospedale americano ha esaminato 402 protesi totali di ginocchio impiantate con l'aiuto di un robot, guardando come cambia l'inclinazione dell'articolazione rispetto a prima dell'intervento. Il cambiamento non ha peggiorato l'equilibrio della protesi durante l'operazione.", "Lo studio guarda come è andata l'operazione, non come stanno i pazienti nel tempo: non permette di dire che un modo di impiantare sia preferibile."], "kw": "protesi totale ginocchio robotica, protesi ginocchio robot, equilibrio protesi ginocchio"}, "4": {"prof": ["TKA robotica MAKO: approccio e inserto spostano di circa 1° l'inclinazione rotulea", "Uno studio radiografico retrospettivo (Journal of Experimental Orthopaedics, ottobre 2026; Lione) su 320 TKA MAKO senza resurfacing rotuleo, in quattro gruppi per approccio (mini-subvastus, parapatellare mediale) e inserto (condilare stabilizzato, posteriore stabilizzato), trova una tilt rotulea maggiore di circa 1° con mini-subvastus e con inserto condilare stabilizzato, nessuna interazione fra approccio e inserto e altezza rotulea invariata. Intervalli di confidenza non riportati nell'abstract.", "Nota critica: solo radiografie statiche, nessun esito clinico né tracking dinamico; gruppi non randomizzati; gli autori stessi giudicano trascurabile l'effetto radiografico."], "mix": ["Protesi totale con robot MAKO: l'inclinazione della rotula cambia di circa un grado", "Un centro di Lione ha confrontato, su 320 protesi totali di ginocchio impiantate con il robot MAKO, due vie d'accesso e due tipi di inserto in plastica, misurando sulle radiografie come è inclinata la rotula. Le differenze fra i quattro gruppi sono di circa un grado e l'altezza della rotula non cambia.", "Nota sul limite: si guardano solo radiografie ferme, senza punteggi riferiti dal paziente né movimento; non si sa se un grado conti nella vita di tutti i giorni."], "paz": ["Protesi totale del ginocchio con robot: la rotula resta ben allineata con approcci e inserti diversi", "Un ospedale francese ha controllato sulle radiografie la posizione della rotula in 320 persone operate di protesi totale di ginocchio con l'aiuto di un robot, con due vie d'accesso e due tipi di inserto. Le differenze erano di circa un grado.", "Lo studio guarda solo le radiografie e non dice come stanno i pazienti: non permette di dire se un modo di operare sia preferibile."], "kw": "protesi totale ginocchio, rotula dopo protesi, protesi robotica ginocchio"}, "5": {"prof": ["Attività sportiva dopo UKA a 6,8 anni: un paziente su tre pratica, il 75% riferisce limitazioni", "Un questionario elettronico retrospettivo (Journal of Experimental Orthopaedics, ottobre 2026; Santiago del Cile) su 150 pazienti con UKA primaria (risposta 78,9%; età 65,1 ± 10,9; follow-up 6,8 ± 2,4 anni) riferisce una partecipazione attuale del 33,3% (8,0% un anno prima dell'intervento, 25,3% un anno dopo). Ripresa entro 12 mesi nel 49,3%; limitazioni nell'attività 75,3%, restrizioni a lungo termine 30,0%; sesso maschile e intensità migliorata: OR aggiustato 2,08 (IC 95% 0,90-4,80).", "Nota critica: dati storici ricordati dal paziente, 21% di non rispondenti, nessun gruppo di confronto; le proporzioni di gruppo non descrivono il recupero del singolo."], "mix": ["Dopo la protesi parziale del ginocchio, a quasi sette anni un paziente su tre fa sport", "Un centro cileno ha scritto a 190 pazienti operati di protesi che sostituisce una sola parte del ginocchio; 150 hanno risposto. A circa sette anni dall'intervento un terzo pratica sport o attività fisica, la maggior parte per più di tre ore a settimana; metà ha ripreso entro dodici mesi e tre su quattro riferiscono qualche limitazione.", "Nota sul limite: le risposte su prima dell'intervento sono ricordi, un quinto dei pazienti non ha risposto e manca un gruppo di confronto."], "paz": ["Protesi parziale del ginocchio: come va con l'attività fisica dopo quasi sette anni", "In uno studio cileno su 150 persone con una protesi che sostituisce una sola parte del ginocchio, dopo circa sette anni un terzo praticava sport o attività fisica; metà aveva ripreso entro un anno dall'intervento e molti riferivano comunque qualche limitazione.", "Le risposte si basano sui ricordi delle persone e non c'è un gruppo di confronto: i risultati non dicono cosa aspettarsi in un singolo caso."], "kw": "protesi parziale ginocchio sport, attività fisica dopo protesi ginocchio, ripresa sport protesi"}, "6": {"prof": ["LCA con hamstring a fascio singolo: asse coronale invariato a 5 anni, il varo si associa a Lysholm più basso", "Una coorte retrospettiva monocentrica (Indian Journal of Orthopaedics; Kocaeli) su 100 LCA primari con hamstring, con radiografie dell'arto intero a 60 ± 14 mesi, non trova differenze fra lato operato e controlaterale: HKA 177,3° ± 3,3 contro 177,7° ± 3,1, mLDFA, MPTA, JLCA e MAD con p>0,05. La deviazione in varo si correla a un Lysholm più basso (r -0,28; p=0,01); le lesioni meniscali (43) non incidono sull'allineamento.", "Nota critica: nessuna radiografia preoperatoria dell'arto intero, il controlaterale è il solo riferimento; «nessuna differenza» con questa numerosità non è prova di equivalenza; correlazione debole, senza correzione per i confondenti."], "mix": ["Dopo il legamento crociato con i tendini della coscia, l'asse della gamba resta invariato a cinque anni", "Un ospedale turco ha misurato sulle radiografie dell'intera gamba 100 pazienti operati di legamento crociato, a circa cinque anni dall'intervento, e ha confrontato la gamba operata con l'altra: l'asse risulta simile (177,3 gradi contro 177,7). Chi aveva una gamba più storta verso l'interno aveva punteggi funzionali un po' più bassi.", "Nota sul limite: non c'erano radiografie dell'intera gamba prima dell'operazione, quindi si confronta solo con l'altro lato, e un legame debole non dimostra una causa."], "paz": ["Dopo l'operazione al crociato l'asse della gamba resta simile a quello dell'altra gamba", "Uno studio turco su 100 persone operate di legamento crociato ha misurato, circa cinque anni dopo, l'asse della gamba sulle radiografie e l'ha confrontato con quello dell'altra gamba: i valori erano simili. Chi aveva la gamba più storta verso l'interno aveva in media punteggi un po' più bassi.", "Lo studio non ha radiografie prima dell'operazione e non dimostra una causa: i risultati vanno discussi con il proprio ortopedico."], "kw": "legamento crociato anteriore, asse della gamba dopo operazione, allineamento ginocchio"}, "7": {"prof": ["TKA con allineamento cinematico ristretto e guide patient-specific da TC: serie prospettica indiana su 246", "Una serie prospettica monocentrica di un chirurgo (Indian Journal of Orthopaedics; Chennai) su 246 TKA con guide da TC (PERFIT-R) in allineamento cinematico ristretto riferisce, a 6-18 mesi, un miglioramento di WOMAC, OKS, KSS, SF-12 fisico ed EQ-5D (p<0,05), resezioni entro ±1 mm dal pianificato, complicanze del 2,0% e nessuna revisione. Intervalli di confidenza non riportati nell'abstract.", "Nota critica: nessun gruppo di controllo, nessuna validazione radiografica standardizzata dell'allineamento ottenuto, follow-up troppo breve per la sopravvivenza dell'impianto, ginocchia in valgo escluse."], "mix": ["Protesi totale con guide su misura: uno studio indiano su 246 pazienti a 6-18 mesi", "Un ospedale di Chennai ha operato 246 pazienti di protesi totale di ginocchio con guide costruite su misura da una TAC, cercando di rispettare la forma originale del ginocchio entro limiti di sicurezza. A 6-18 mesi i punteggi riferiti dai pazienti sono migliorati e i tagli ossei erano entro un millimetro da quanto pianificato; le complicanze sono state il 2,0%.", "Nota sul limite: non c'è un gruppo di confronto e non si misura l'allineamento finale; 18 mesi non bastano per giudicare la durata della protesi."], "paz": ["Protesi totale del ginocchio con guide su misura: i risultati a 18 mesi in uno studio indiano", "Un ospedale indiano ha operato 246 pazienti di protesi totale di ginocchio usando guide preparate su misura a partire da una TAC. A 6-18 mesi i punteggi riferiti dai pazienti erano migliorati e le complicanze erano poche.", "Lo studio non confronta questo metodo con altri e dura poco: non permette di dire se sia preferibile."], "kw": "protesi totale ginocchio, guide su misura protesi ginocchio, allineamento protesi ginocchio"}, "8": {"prof": ["Gonartrosi: copertura meniscale e spessore cartilagineo alla RM spiegano l'asse meccanico come la JLCA", "Uno studio trasversale (Journal of Experimental Orthopaedics, ottobre 2026; Tokyo) su 94 ginocchia di 89 donne con KL 0-4 mostra che l'aHKA spiega il 67% della varianza dell'asse meccanico (R² aggiustato 0,668); aggiungendo la JLCA si arriva a 0,840, aggiungendo copertura meniscale mediale e differenza di spessore cartilagineo alla RM a 0,841 (tutti i predittori p<0,01).", "Nota critica: disegno trasversale senza direzione causale, solo donne e centro unico, nessuna validazione esterna; non si dice se la RM aggiunga qualcosa alla pianificazione di un'osteotomia."], "mix": ["Artrosi del ginocchio: la risonanza di menisco e cartilagine aiuta a spiegare l'asse della gamba", "Un gruppo di Tokyo ha misurato l'asse della gamba in carico su 94 ginocchia di donne con artrosi di gravità variabile, insieme alla copertura del menisco interno e allo spessore della cartilagine alla risonanza. Queste misure, aggiunte a quelle sulle radiografie, spiegano l'asse tanto quanto la misura radiografica dell'inclinazione dell'articolazione (circa l'84% della variabilità contro il 67% di partenza).", "Nota sul limite: è una fotografia in un momento solo, in sole donne e in un solo centro; non dice se servano nella scelta di un'operazione."], "paz": ["Artrosi del ginocchio: la risonanza fornisce informazioni in più sull'asse della gamba", "Uno studio di Tokyo su 94 ginocchia di donne con artrosi ha visto che le misure del menisco e della cartilagine alla risonanza aiutano a spiegare come è allineata la gamba, insieme a quelle delle radiografie.", "È uno studio fatto in un solo momento e in un solo centro: non indica come curare e non sostituisce la valutazione dello specialista."], "kw": "artrosi del ginocchio, risonanza ginocchio menisco, asse della gamba"}};

var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Experimental Orthopaedics",h:"Simmetria dei flessori dopo LCA: dal 98% al 55% secondo il test",v:"Prospettico su 68 pazienti con LCA hamstring (71 sedute, mediana 12 mesi) e 33 controlli con innesto rotuleo o quadricipitale: simmetria di forza 98,4% al Biodex seduto, 85,3% con Nordic hamstring, 64,1% e 54,5% con le due prove isometriche prone; differenza Biodex-ISO90 PF 43,9% (IC 95% 39,9-47,8). Nei controlli le differenze fra test sono di circa 6 punti.",ax:"Högberg, Wernbom, Sundberg, Hermansson, Larsson, Adell, Samuelsson, Hamrin Senorski",date:"ott 2026",meta:"studio prospettico comparativo da registro di riabilitazione, 68 pazienti con innesto hamstring + 33 controlli con innesto rotuleo/quadricipitale, Göteborg · [II]",pmid:'42829679',doi:'10.1002/jeo2.70932',journal:"Journal of experimental orthopaedics",authors:"Högberg J, Wernbom M, Sundberg A, Hermansson E, Larsson T, Adell F, Samuelsson K, Hamrin Senorski E",design:"Studio prospettico osservazionale su Project ACL, registro di riabilitazione svedese (Göteborg) attivo dal 2014 (linee guida RECORD); dati giugno 2024-agosto 2025. Quattro test di flessione del ginocchio nella stessa seduta, almeno 4 mesi dopo il LCA: Biodex seduto in concentrico a 90°/s, Nordic hamstring con NordBord (eccentrico), due isometriche prone a 90° di flessione con caviglia in dorsiflessione (ISO90 DF) o in flessione plantare (ISO90 PF). Esito primario: indice di simmetria (LSI, arto operato/sano) fra i test, con t di Student per dati appaiati; secondario: quota con LSI ≥90% (McNemar). Controllo: pazienti con innesto rotuleo o quadricipitale dello stesso registro. Testo completo letto su PMC.",pop:"68 pazienti con innesto di hamstring (71 sedute di test; età 25 ± 8 anni, 32% uomini, test a una mediana di 12 mesi dal LCA; Tegner pre-infortunio mediano 9) e 33 controlli (34 sedute; innesto rotuleo in 32, quadricipitale in 1; età 26 ± 11). La NordBord è stata eseguita solo da 18 controlli (55%) per dolore da inginocchiamento al sito di prelievo. Sintomi agli hamstring: 39% contro 3% (p<0,001).",results:"LSI nei pazienti con hamstring: Biodex 98,4% ± 10,5%; NordBord 85,3% ± 14,4%; ISO90 DF 64,1% ± 13,6%; ISO90 PF 54,5% ± 16,0%. Differenza Biodex contro ISO90 PF 43,9% ± 16,7% (IC 95% 39,9-47,8; p<0,001; d=2,62), contro NordBord 13,1% (IC 95% 9,8-16,4), contro ISO90 DF 34,3%. Quota con LSI ≥90%: 80% (Biodex), 42% (NordBord), 6% (ISO90 DF), 3% (ISO90 PF). Controlli: LSI 98,0% ± 11,5% (Biodex), 97,5% ± 10,3%, 92,8% ± 11,9%, 91,9% ± 12,5%; differenza Biodex-ISO90 PF 6,1% (IC 95% 1,7-10,6; p=0,009); quota ≥90% nell'ISO90 PF 59%. Hamstring contro controlli: Biodex differenza 0,4% (IC 95% da -4,1 a 4,9; p=0,86), NordBord -12,2% (IC 95% da -19,4 a -5,0), ISO90 DF -28,8% (IC 95% da -34,2 a -23,3), ISO90 PF -37,4% (IC 95% da -43,6 a -31,2).",concl:"Gli autori: l'LSI dei flessori varia molto con la modalità di test dopo LCA con hamstring; sono da considerare posizione di anca, ginocchio e caviglia e il tipo di contrazione, e nessun test singolo basta a monitorare il recupero.",limits:"Test eseguiti nella stessa seduta, ordine non randomizzato: fatica e ordine possono pesare, e contrazione e posizione non si separano · controllo piccolo (33; NordBord solo in 18) e fatto quasi tutto di innesto rotuleo (32 su 33), non è un gruppo sano né un innesto quadricipitale · taglio trasversale a una mediana di 12 mesi, la rigenerazione del semitendinoso continua fino a 2 anni · nessun esito duro: gli autori stessi dichiarano incerta la rilevanza clinica dei deficit nelle prove prone e le soglie da raggiungere · semitendinoso solo o con gracile non distinto.",perte:"Il tuo innesto è il retto femorale o il tendine quadricipitale: qui si misurano i flessori dopo hamstring e il controllo è quasi tutto rotuleo (32 su 33), quindi non è trasferibile al deficit estensorio del tuo innesto. Tocca però la tensione sul criterio di rientro (T3 nel cervello): «LSI ≥90%» cambia verdetto con lo stesso paziente secondo strumento, posizione e contrazione (80% o 3% sopra soglia), quindi un valore di simmetria va sempre letto insieme al test con cui è stato ottenuto."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Experimental Orthopaedics",h:"UKA laterale ≤55 anni: nessuna revisione del componente, 7 reinterventi su 84",v:"Serie retrospettiva da database prospettico, 84 UKA laterali fixed-bearing in 80 pazienti ≤55 anni, follow-up medio 5,3 ± 1,9 anni: nessuna revisione del componente laterale; sopravvivenza libera da reintervento a 5 anni 92,5% (IC 95% 86,8-98,2). Sette reinterventi, quattro dei quali UKA mediali per progressione dell'artrosi.",ax:"Abdulai, Schweizer, Rühle, Krug, Morgenbesser, Herre, Aldinger, Merle, Waldstein",date:"ott 2026",meta:"serie di casi retrospettiva da database prospettico, 84 UKA laterali fixed-bearing in 80 pazienti ≤55 anni, Stoccarda · [IV]",pmid:'42829640',doi:'10.1002/jeo2.70935',journal:"Journal of experimental orthopaedics",authors:"Abdulai S, Schweizer C, Rühle V, Krug T, Morgenbesser R, Herre J, Aldinger PR, Merle C, Waldstein W",design:"Serie consecutiva retrospettiva da database istituzionale tenuto prospetticamente (Orthopädische Klinik Paulinenhilfe, Stoccarda): UKA laterali primarie fixed-bearing, gennaio 2016-dicembre 2021, follow-up minimo 2 anni. Kaplan-Meier per sopravvivenza alla revisione del componente laterale (rimozione o sostituzione di qualunque componente fisso) e al reintervento di qualunque tipo; esiti funzionali con Oxford Knee Score e UCLA; angolo anca-ginocchio-caviglia (HKAA) radiografico.",pop:"84 UKA laterali primarie in 80 pazienti di 55 anni o meno (età media 51, 37-55); follow-up medio 5,3 ± 1,9 anni (2,2-8,6).",results:"Sopravvivenza alla revisione del componente laterale 100%; sopravvivenza libera da reintervento a 5 anni 92,5% (IC 95% 86,8-98,2). Sette reinterventi: quattro UKA mediali aggiuntive, due artroscopie, un debridement con antibiotici e ritenzione dell'impianto (DAIR). HKAA da 4,8° ± 4,7° di valgo a 2,0° ± 2,8°; il residuo di valgo è maggiore nelle ginocchia senza progressione mediale o osteonecrosi che in quelle con (2,2° di valgo contro 1,5° di varo; p=0,012, su quattro ginocchia). OKS postoperatorio 43,8 ± 5,7; UCLA 6,5 ± 1,2.",concl:"Gli autori: la UKA laterale fixed-bearing nei pazienti più giovani si associa a sopravvivenza del componente laterale del 100% e a punteggi funzionali alti a circa 5 anni; la progressione dell'artrosi mediale è il motivo più frequente di reintervento; l'associazione fra varismo postoperatorio e progressione richiede conferma.",limits:"Serie senza gruppo di confronto: nessuna misura rispetto a UKA mediale, osteotomia o protesi totale · zero revisioni su 84 non vuol dire rischio zero: con la regola del tre il limite superiore indicativo è intorno al 3,6% (vedi studio muto) · follow-up medio di 5 anni, perdite al follow-up non riportate nell'abstract · l'associazione varismo-progressione poggia su quattro ginocchia, come dicono gli autori.",perte:"Fai la protesi monocompartimentale: qui è la laterale, in pazienti giovani (≤55 anni). Il risultato è favorevole ma senza gruppo di confronto, quindi non dice se un'alternativa (UKA mediale, osteotomia, protesi totale) avrebbe fatto meglio o peggio. Non muove nessuna tensione."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Experimental Orthopaedics",h:"TKA robotica: cambiare l'obliquità della rima non peggiora l'equilibrio",v:"Serie retrospettiva di un chirurgo (HSS), 402 TKA primarie robot-assistite: tipo CPAK cambiato in 300 (74,6%), zona di obliquità della rima (JLO) in 221 (55,0%). Una variazione maggiore di JLO si associa a minore squilibrio in flessione (β -0,060; p<0,001) e a lassità in estensione più stretta (β -0,055; p=0,002); nessuna associazione con il KOOS JR.",ax:"Morita, Shin, El-Hassan, Shichman, Long, Sculco",date:"ott 2026",meta:"coorte retrospettiva monocentrica di un chirurgo, 402 TKA primarie robot-assistite, Hospital for Special Surgery New York · [III]",pmid:'42829598',doi:'10.1002/jeo2.70936',journal:"Journal of experimental orthopaedics",authors:"Morita Y, Shin J, El-Hassan M, Shichman I, Long WJ, Sculco PK",design:"Serie retrospettiva di un chirurgo (Complex Joint Reconstruction Center, Hospital for Special Surgery, New York): TKA primarie robot-assistite. Angolo anca-ginocchio-caviglia aritmetico (aHKA), obliquità della rima articolare (JLO) e tipo CPAK da radiografie dell'arto intero pre e postoperatorie. Esiti primari: squilibrio finale in estensione e in flessione e range di lassità dopo l'impianto di prova; modelli multivariabili sulle variazioni con segno e in valore assoluto; analisi di supporto sulla ridistribuzione delle resezioni e su un sottogruppo varo.",pop:"402 TKA primarie robot-assistite di un chirurgo; piattaforma robotica non indicata nell'abstract.",results:"Cambio di tipo CPAK in 300 ginocchia (74,6%), di zona JLO in 221 (55,0%). Maggiore ΔJLO: minore squilibrio finale in flessione (β -0,060; p<0,001) e range di lassità in estensione più stretto (β -0,055; p=0,002); in valore assoluto β -0,046 (p=0,018) e -0,070 (p=0,004). Né ΔaHKA con segno né in valore assoluto è associato a squilibrio in estensione o flessione. Nelle ginocchia in varo la riduzione del varo tibiale si associa a maggiori ΔJLO e ΔaHKA, correzione coronale femorale e minore squilibrio in flessione. Nessuna associazione di |ΔaHKA| o |ΔJLO| con il miglioramento del KOOS JR. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: la variazione di JLO si accompagna a un equilibrio finale migliore piuttosto che peggiore e può riflettere aspetti specifici dell'equilibrio finale, non una deviazione indesiderata dal fenotipo nativo.",limits:"Retrospettivo, un solo chirurgo, nessun gruppo di confronto: associazioni, non effetto dell'allineamento scelto · l'equilibrio è misurato con l'impianto di prova, non è un esito clinico, e il KOOS JR non risulta associato a nessuna delle variazioni · piattaforma robotica e filosofia di allineamento non descritte nell'abstract · intervalli di confidenza non riportati.",perte:"Fai la TKA con VELYS: l'abstract non dice quale robot sia stato usato, ma il tema — quanto ci si allontana dal fenotipo nativo, e come si legge l'equilibrio intraoperatorio — è lo stesso del tuo planning. Il dato è un'associazione sull'equilibrio, non sull'esito del paziente. Non muove nessuna tensione."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Experimental Orthopaedics",h:"TKA robotica MAKO: approccio e inserto spostano la tilt rotulea di circa 1°",v:"Studio radiografico retrospettivo su 320 TKA MAKO senza resurfacing rotuleo in quattro gruppi (mini-subvastus CS 134 e PS 63, parapatellare mediale CS 75 e PS 48): tilt rotulea maggiore di circa 1° con subvastus e con inserto CS, nessuna interazione fra approccio e inserto, altezza rotulea invariata. Esiti clinici non misurati.",ax:"Favroul, Kaitouni, Servien, Batailler, Lustig",date:"ott 2026",meta:"studio radiografico retrospettivo comparativo, 320 TKA primarie MAKO senza resurfacing rotuleo, Lione · [IV]",pmid:'42829593',doi:'10.1002/jeo2.70933',journal:"Journal of experimental orthopaedics",authors:"Favroul C, Kaitouni MD, Servien E, Batailler C, Lustig S",design:"Studio radiografico retrospettivo comparativo (Hôpital de la Croix-Rousse, Lione): TKA primarie con robot MAKO, marzo 2021-dicembre 2024, quattro gruppi per approccio (mini-subvastus MSV, parapatellare mediale MPP) e inserto (condilare stabilizzato CS, posteriore stabilizzato PS). Radiografie assiali di Merchant a 30° e laterali a 2 mesi e a 1 anno. Esito primario: tilt rotulea; secondari: centratura qualitativa, spessore rotuleo, indice di Blackburne-Peel modificato. Analisi fattoriale a due vie per approccio, inserto e interazione.",pop:"320 TKA primarie MAKO senza resurfacing: MSV-CS 134, MSV-PS 63, MPP-CS 75, MPP-PS 48; caratteristiche di base e parametri robotici finali comparabili.",results:"Tilt rotulea statisticamente maggiore con MSV rispetto a MPP e con CS rispetto a PS, ma la differenza assoluta è di circa 1°; nessuna interazione significativa fra approccio e inserto; altezza rotulea senza differenze. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: il posizionamento funzionale robotico dà un allineamento femororotuleo statico costante a prescindere da approccio e vincolo dell'inserto; la differenza di circa 1° è un effetto radiografico trascurabile, con significato clinico ignoto.",limits:"Solo radiografie statiche: nessun esito clinico né tracking dinamico (lo dicono gli autori) · retrospettivo, gruppi non randomizzati, quindi approccio e inserto possono dipendere da scelte del chirurgo · nessun intervallo di confidenza nell'abstract: la «significatività» su circa 1° non dice nulla sul peso clinico · piattaforma MAKO, non VELYS.",perte:"Fai la TKA robotica con VELYS: qui è MAKO, ma il tema — se approccio e vincolo dell'inserto influenzino la femororotulea con un planning funzionale — vale anche per te. Il risultato dice di no sul piano radiografico. Non muove nessuna tensione."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Experimental Orthopaedics",h:"Attività dopo UKA a 6,8 anni: pratica sport un paziente su tre",v:"Questionario elettronico retrospettivo su 150 UKA (risposta 78,9%; età 65,1 ± 10,9; follow-up 6,8 ± 2,4 anni): partecipazione ricordata 33,3% oggi contro 8,0% un anno prima dell'intervento; ripresa entro 12 mesi 49,3%; limitazioni riferite 75,3%, restrizioni a lungo termine 30,0%. Nessun confronto significativo per sesso.",ax:"Gonzalez, Isla, Barba, Erskine, Landea, Tapia, Figueroa",date:"ott 2026",meta:"studio retrospettivo monoistituzionale con questionario elettronico, 150 UKA primarie, Santiago del Cile · [IV]",pmid:'42829620',doi:'10.1002/jeo2.70929',journal:"Journal of experimental orthopaedics",authors:"Gonzalez W, Isla J, Barba D, Erskine D, Landea D, Tapia C, Figueroa D",design:"Studio retrospettivo monoistituzionale (Clínica Alemana, Santiago): UKA primarie 2014-2022; questionario elettronico di 11 voci somministrato nel 2025 su attività a 5 anni e a 1 anno prima della UKA, a 1 anno dopo e oggi. Esito primario: partecipazione attuale; le risposte storiche sono stime ricordate dal paziente.",pop:"150 rispondenti su 190 contattabili (78,9%); età media 65,1 ± 10,9 anni; follow-up medio 6,8 ± 2,4 anni.",results:"Partecipazione ricordata: 33,3% a 5 anni prima, 8,0% a 1 anno prima, 25,3% a 1 anno dopo, 33,3% oggi. Fra chi pratica oggi: 74,0% oltre 3 ore a settimana, 48,0% sforzo almeno moderato. Ripresa entro 12 mesi 49,3%; miglioramento percepito 42,0%; soddisfazione media 3,84 ± 1,30; limitazioni nell'attività 75,3%, restrizioni a lungo termine 30,0%. Sesso maschile e intensità migliorata: OR aggiustato 2,08 (IC 95% 0,90-4,80), non significativo.",concl:"Gli autori: a lungo termine dopo UKA un terzo dei pazienti riferisce sport o attività, la maggior parte con oltre 3 ore a settimana, ma solo la metà riprende entro 12 mesi e le limitazioni residue sono frequenti; le proporzioni di gruppo storiche non vanno lette come recupero individuale.",limits:"Retrospettivo, dati storici ricordati dal paziente (bias di memoria) · 21% di non rispondenti: la partecipazione potrebbe essere sovra o sottostimata · nessun gruppo di confronto (TKA, osteotomia, controlli) · lo studio non misura il livello sportivo né l'esito oggettivo; l'IC 0,90-4,80 sul sesso è molto largo.",perte:"Fai UKA: è un dato utile per l'informazione preoperatoria sul ritorno allo sport (un paziente su tre pratica attività a 6,8 anni, metà riprende entro un anno), con tutti i limiti di un questionario retrospettivo. Non muove nessuna tensione."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"Indian Journal of Orthopaedics",h:"LCA con hamstring: l'asse della gamba resta invariato a 5 anni",v:"Coorte retrospettiva di 100 LCA primari con hamstring a fascio singolo, radiografie dell'arto intero a 60 ± 14 mesi: HKA 177,3° ± 3,3 contro 177,7° ± 3,1 nel lato sano, nessuna differenza (p>0,05) per HKA, mLDFA, MPTA, JLCA, MAD; il varo si correla a Lysholm più basso (r -0,28; p=0,01).",ax:"İnce, Oğur, Çiçek, Seyfettinoğlu, Pazarcı, Çiçek",date:"feb 2026 (in PubMed da ott)",meta:"coorte retrospettiva monocentrica, 100 LCA primari con hamstring a fascio singolo, Kocaeli · [IV]",pmid:'42824328',doi:'10.1007/s43465-026-01699-0',journal:"Indian journal of orthopaedics",authors:"İnce M, Oğur HU, Çiçek H, Seyfettinoğlu F, Pazarcı Ö, Çiçek O",design:"Coorte retrospettiva monocentrica (Kocaeli Derince Training & Research Hospital): 100 pazienti consecutivi con LCA primario 2013-2018, innesto hamstring a fascio singolo. Radiografie dell'arto intero in carico a una media di 60 ± 14 mesi: HKA, mLDFA, MPTA, JLCA e deviazione dell'asse meccanico (MAD) sul lato operato e controlaterale; esito funzionale con Tegner-Lysholm; t appaiati e correlazioni di Spearman.",pop:"100 pazienti consecutivi con LCA primario (2013-2018), 43 con lesione meniscale associata.",results:"Operato contro controlaterale: HKA 177,3° ± 3,3 contro 177,7° ± 3,1; mLDFA 87,6° ± 2,5 contro 87,4° ± 2,2; MPTA 85,6° ± 2,3 contro 85,6° ± 2,2; JLCA 1,11° ± 1,8 contro 0,72° ± 1,17; MAD 5,96 ± 18,1 mm contro 3,68 ± 8,9 mm; tutti p>0,05. La deviazione in varo della MAD si correla a Lysholm più basso (r -0,28; p=0,01); l'IMC a più varo (r 0,32; p=0,02). Le lesioni meniscali (43) non hanno effetto sui parametri di allineamento.",concl:"Gli autori: il LCA primario mantiene l'allineamento coronale a 5 anni, ma la deviazione in varo si associa a esiti funzionali peggiori, e sottolineano l'importanza di affrontare il malallineamento postoperatorio.",limits:"Retrospettivo, senza radiografia preoperatoria dell'arto intero: il controlaterale è il solo riferimento, e non è detto che fosse sano · «nessuna differenza» con 100 pazienti e deviazioni standard di circa 3° non è prova di equivalenza (vedi studio muto) · correlazioni deboli (r -0,28) senza correzione per fattori di confondimento · l'abstract su PubMed contiene in coda un paragrafo non coerente con il resto (valori diversi, «1,5° → 1,7°»), ignorato qui: i numeri sono quelli del corpo dell'abstract.",perte:"Innesto hamstring a fascio singolo, senza LET: non è il tuo innesto né la tua combinazione. Rilevante come dato di base: se il crociato di per sé non cambia l'asse, un varo a distanza va letto come malallineamento preesistente o progressivo, utile per chi poi valuta slope e osteotomia. Non muove nessuna tensione."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Indian Journal of Orthopaedics",h:"TKA con allineamento cinematico ristretto e guide su misura: serie indiana",v:"Serie prospettica monocentrica di un chirurgo, 246 TKA con guide patient-specific da TC (PERFIT-R), follow-up 6-18 mesi: miglioramento di WOMAC, OKS, KSS, SF-12 fisico ed EQ-5D (p<0,05), resezioni entro ±1 mm dal pianificato, complicanze 2,0%, nessuna revisione. Nessun gruppo di controllo.",ax:"Rs, Loganathan, S",date:"giu 2026 (in PubMed da ott)",meta:"studio osservazionale prospettico monocentrico di un chirurgo, 246 TKA con allineamento cinematico ristretto, Chennai · [IV]",pmid:'42824660',doi:'10.1007/s43465-026-01844-9',journal:"Indian journal of orthopaedics",authors:"Rs B, Loganathan B, S S",design:"Studio osservazionale prospettico monocentrico di un chirurgo (Soundarapandian Bone and Joint Hospital, Chennai), pazienti ≥50 anni con artrosi primaria, gennaio 2022-gennaio 2024: TKA con allineamento cinematico ristretto (rKA) guidato da un sistema di guide patient-specific da TC sviluppato in India (PERFIT-R); ginocchia in valgo escluse. Esiti con WOMAC, OKS, KSS, SF-12, EQ-5D e Forgotten Joint Score a 6, 12 e 18 mesi; concordanza fra resezioni pianificate e ottenute con calibro intraoperatorio.",pop:"246 pazienti, età 64 ± 8,9 anni, 13,8% uomini; follow-up 6-18 mesi.",results:"Miglioramento significativo di WOMAC, OKS, KSS, SF-12 componente fisica ed EQ-5D nel follow-up (p<0,05), oltre le MCID di letteratura (derivate da altre popolazioni e non validate nella coorte); Forgotten Joint Score stabile. Resezioni ossee entro ±1 mm da quanto pianificato; complicanze 2,0%, nessuna revisione. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: la rKA con guide su misura da TC è fattibile in una coorte selezionata, con esecuzione coerente e tendenza favorevole degli esiti precoci; i risultati sono preliminari e da confermare con studi comparativi, allineamento radiografico oggettivo e follow-up più lungo.",limits:"Nessun gruppo di controllo, nessuna validazione radiografica standardizzata dell'allineamento: la concordanza misura l'esecuzione, non l'allineamento ottenuto (lo dicono gli autori) · 6-18 mesi non misurano la sopravvivenza dell'impianto · un solo chirurgo, ginocchia in valgo escluse, 86% donne · MCID mutuate da altre popolazioni.",perte:"Non è il tuo sistema (VELYS) né un confronto: guide su misura da TC in allineamento cinematico ristretto. Entra per il perimetro (protesi totale), come dato di fattibilità, non di superiorità. Non muove nessuna tensione."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Journal of Experimental Orthopaedics",h:"Gonartrosi: RM di menisco e cartilagine spiega l'asse come la JLCA",v:"Studio trasversale su 94 ginocchia di 89 donne (età 54,6 anni, KL 0-4): l'aHKA da solo spiega il 67% della varianza dell'asse meccanico (R² aggiustato 0,668); con la JLCA 0,840, con copertura meniscale mediale e differenza di spessore cartilagineo alla RM 0,841 (tutti p<0,01).",ax:"Sasabe, Ozeki, Katano, Nakagawa, Nakamura, Koga, Sekiya",date:"ott 2026",meta:"studio trasversale, 94 ginocchia di 89 donne con gonartrosi KL 0-4, Tokyo · [III]",pmid:'42829635',doi:'10.1002/jeo2.70927',journal:"Journal of experimental orthopaedics",authors:"Sasabe A, Ozeki N, Katano H, Nakagawa Y, Nakamura T, Koga H, Sekiya I",design:"Studio trasversale (Institute of Science Tokyo): ginocchia di donne con KL 0-4; radiografie in carico dell'arto intero (percentuale di asse meccanico %MA, aHKA, MPTA, JLCA) e RM tridimensionale (copertura meniscale mediale MMCR, spessore cartilagineo). Regressioni multiple che confrontano il contributo di JLCA o di misure RM aggiunte all'aHKA; interazione MPTA per gravità dell'artrosi.",pop:"94 ginocchia di 89 donne, età media 54,6 anni, KL da 0 a 4.",results:"MPTA correlato alla copertura meniscale mediale solo nelle ginocchia con artrosi avanzata (KL 3-4; r=0,404) e non in quelle KL 0-2 (r=0,064); interazione MPTA per gravità non significativa (p=0,116). Modello A (aHKA): R² aggiustato 0,668; B (aHKA + JLCA): 0,840; C (aHKA + MMCR + differenza di spessore cartilagineo mediale-laterale): 0,841, tutti i predittori p<0,01; modello combinato 0,864.",concl:"Gli autori: le misure RM di copertura meniscale e spessore della cartilagine, aggiunte all'aHKA, spiegano l'asse meccanico in carico quanto la JLCA e possono dare informazioni strutturali complementari alla valutazione radiografica.",limits:"Trasversale: nessuna direzione causale, e le associazioni non dicono se la RM aggiunga qualcosa alla pianificazione di un'osteotomia · solo donne, centro unico, 94 ginocchia su KL 0-4 (pochi per sottogruppo) · R² in campione di sviluppo, senza validazione esterna · interazione non significativa: la differenza per gravità è solo suggerita.",perte:"Tocca la pianificazione dell'osteotomia (asse meccanico, JLCA, meccanica del menisco) ma senza alcuna correzione chirurgica: è un dato di descrizione, non di esito. Nessun conflitto con la tua pratica. Non muove nessuna tensione."}];

var SUGGQ=[{"k": "kol", "n": "C. Batailler (Lione, Francia)", "w": "Lione, Francia — coautrice dello studio radiografico di oggi su 320 protesi totali robotiche MAKO (PMID 42829593, afferenza letta nei metadati PubMed: Orthopaedics Surgery and Sports Medicine Department, FIFA Medical Center of Excellence, Croix-Rousse Hospital, Hospices Civils de Lyon); corrispondenza tecnica con la tua protesi totale robotica (VELYS), con un centro che pubblica sul posizionamento funzionale. Sostituisce C. M. Gupte (4 ottobre, nessun segnale dell'utente arrivato per farlo ruotare)."}];

var BRIEF_TEXT="Oggi, lunedì 5 ottobre, otto lavori e nessuna scheda rossa né arancione: nessun richiamo di dispositivi nuovo, nessuna ritrattazione che ti riguardi, nessun nuovo consensus o linea guida oltre a quelli già visti. Il lavoro del giorno è uno studio prospettico del registro Project ACL di Göteborg, nel Journal of Experimental Orthopaedics: dopo il crociato con innesto hamstring, a una mediana di dodici mesi, la simmetria di forza dei flessori dipende dal test. Con il Biodex da seduti è 98,4%; con il Nordic hamstring 85,3%; con le due prove isometriche prone a novanta gradi 64,1% e 54,5%. La differenza fra Biodex e prova prona con flessione plantare è 43,9 punti, intervallo di confidenza da 39,9 a 47,8. L'80% dei pazienti supera la soglia del 90% al Biodex, il 3% alla prova prona. Nei trentatré controlli, trentadue con innesto rotuleo e uno quadricipitale, la differenza fra test è di circa sei punti. Non è il tuo innesto: tu usi il retto femorale o il quadricipite, e il deficit atteso è estensorio. Tocca però la tensione sul criterio di rientro: una simmetria sopra il 90% non dice niente se non si dice con quale test. Il limite: prove nella stessa seduta, controllo piccolo, nessun esito duro; non sappiamo se i deficit delle prove prone contino per il rientro. Tra le altre schede: una serie di Stoccarda su ottantaquattro UKA laterali in pazienti di cinquantacinque anni o meno, nessuna revisione del componente laterale e sopravvivenza libera da reintervento a cinque anni del 92,5%, intervallo da 86,8 a 98,2, senza gruppo di confronto. Due lavori sulla protesi totale robotica: a Lione, su trecentoventi MAKO, l'inclinazione rotulea cambia di circa un grado con approccio e inserto; all'Hospital for Special Surgery, su quattrocentodue protesi, una variazione maggiore dell'obliquità della rima non peggiora l'equilibrio in flessione, con p minore di 0,001. Nessuno dei due è il tuo VELYS. Un questionario cileno su centocinquanta UKA riferisce che a sei anni e otto mesi un paziente su tre pratica attività fisica. Nessun'altra tensione si sposta.";

var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi, lunedì 5 ottobre: otto lavori, nessuna scheda rossa né arancione, nessun richiamo nuovo e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "E il lavoro del giorno?"}, {"chi": "A", "t": "Uno studio svedese di Göteborg su sessantotto pazienti operati di crociato con hamstring, a una mediana di dodici mesi. Hanno misurato la forza dei flessori con quattro test diversi."}, {"chi": "B", "t": "E il risultato?"}, {"chi": "A", "t": "Dipende dal test. Da seduti, con il Biodex, la simmetria è 98,4%. Con il Nordic hamstring 85,3%. Nelle due prove prone, 64,1% e 54,5%. La differenza fra la prima e l'ultima è 43,9 punti, intervallo da 39,9 a 47,8."}, {"chi": "B", "t": "Quindi un paziente può passare il criterio del 90% con un test e fallirlo con un altro."}, {"chi": "A", "t": "Esatto: l'80% supera il 90% al Biodex, il 3% alla prova prona."}, {"chi": "B", "t": "Ma tu operi con il retto femorale o il quadricipite, non con l'hamstring."}, {"chi": "A", "t": "Vero, il deficit atteso sul tuo innesto è estensorio, e i controlli qui sono trentadue rotulei e uno quadricipitale. Non è trasferibile. Ma riguarda la tensione sul criterio di rientro: una simmetria va sempre letta con il test con cui è stata ottenuta."}, {"chi": "B", "t": "Limiti?"}, {"chi": "A", "t": "Prove nella stessa seduta, controllo piccolo, nessun esito duro. Non sappiamo se i deficit delle prove prone contino per il rientro."}, {"chi": "B", "t": "E il resto della giornata?"}, {"chi": "A", "t": "Una serie di Stoccarda su ottantaquattro UKA laterali in pazienti di cinquantacinque anni o meno: nessuna revisione del componente laterale, sopravvivenza libera da reintervento a cinque anni del 92,5%, intervallo da 86,8 a 98,2, ma senza gruppo di confronto."}, {"chi": "B", "t": "E la robotica?"}, {"chi": "A", "t": "Due studi sulla protesi totale: a Lione, con MAKO, l'inclinazione rotulea cambia di circa un grado; a New York una variazione maggiore dell'obliquità della rima non peggiora l'equilibrio in flessione. Nessuno dei due è il tuo VELYS."}, {"chi": "B", "t": "Quindi nessuna tensione si sposta, tranne il tassello di metodo sul rientro."}, {"chi": "A", "t": "Esatto."}];

